$ErrorActionPreference='Stop'
$original='C:\Projects\gympro-backups\completion-batch1g-20261025-132147-a68726'
$clean=Join-Path $original 'source'
$report=Join-Path 'C:\Projects\gympro-backups' ('password-change-'+(Get-Date -Format 'yyyyMMddHHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6))
$bin='C:\Program Files\PostgreSQL\18\bin'
$started=$false;$success=$false;$failure=$null
function Run([string]$Exe,[string[]]$Arguments,[string]$Step) {
 Write-Host "CHECK: $Step" -ForegroundColor Cyan
 $old=$ErrorActionPreference
 try {$ErrorActionPreference='Continue'; & $Exe @Arguments; $nativeCode=$LASTEXITCODE} finally {$ErrorActionPreference=$old}
 [IO.File]::WriteAllText((Join-Path $report ($Step+'.exit-code.txt')),[string]$nativeCode)
 if($null -eq $nativeCode -or $nativeCode -ne 0){throw "Step failed: $Step (exit $nativeCode)"}
}
try {
 foreach($step in @('npm-ci','prisma-generate','build')) {
  if((Get-Content (Join-Path $original ($step+'.exit-code.txt')) -Raw).Trim() -ne '0'){throw "Prior check incomplete: $step"}
 }
 $unit=Get-Content (Join-Path $original 'database-independent-results.json') -Raw | ConvertFrom-Json
 if($unit.success -ne $true -or $unit.numPassedTests -lt 1473){throw 'Database-independent evidence incomplete.'}
 foreach($exe in @('initdb.exe','pg_ctl.exe','createdb.exe','psql.exe')){if(-not(Test-Path (Join-Path $bin $exe))){throw "Missing PostgreSQL tool: $exe"}}
 $schema=Join-Path $clean 'sql\baseline-20261016\schema.sql'
 if((Get-FileHash $schema -Algorithm SHA256).Hash.ToLowerInvariant() -ne '24765f818899517aaaa79e39fe7269aae201bcaf774ea4faeff3a8948327ce06'){throw 'Baseline checksum mismatch.'}
 $bootstrapFiles=Join-Path $clean 'sql\bootstrap-prerequisites-20261016'
 $manifest=Get-Content (Join-Path $bootstrapFiles 'manifest.json') -Raw | ConvertFrom-Json
 foreach($entry in @($manifest.files.PSObject.Properties | Where-Object { $_.Name -ne 'README.md' })){if((Get-FileHash (Join-Path $bootstrapFiles $entry.Name) -Algorithm SHA256).Hash.ToLowerInvariant() -cne $entry.Value){throw "Bootstrap checksum mismatch: $($entry.Name)"}}
 New-Item -ItemType Directory -Path $report | Out-Null
 $cluster=Join-Path $report 'pgdata'
 $payload=Join-Path $report 'payload'
 $zip=Join-Path $report 'payload.zip'
 [IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(''))
 Expand-Archive -LiteralPath $zip -DestinationPath $payload
 foreach($name in @('auth-database.service.spec.ts','tenant-membership.integration.spec.ts','session-database.integration.spec.ts')){
  $destination=Join-Path $clean ('src\auth\'+$name)
  Copy-Item -LiteralPath $destination -Destination (Join-Path $report ($name+'.before.bak'))
  Copy-Item -LiteralPath (Join-Path $payload $name) -Destination $destination -Force
 }


 $project='C:\Projects\gympro-api'
 $listener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Parse('127.0.0.1'),3000)
 try{$listener.Start()}catch{throw 'Stop your working API/operator with Ctrl+C before this installation.'}finally{$listener.Stop()}
 $expected=Get-Content (Join-Path $payload 'reviewed-hashes.json') -Raw | ConvertFrom-Json
 foreach($entry in $expected.PSObject.Properties){
  $actual=[IO.File]::ReadAllText((Join-Path $project ('src\auth\'+$entry.Name))).Replace("`r`n","`n")
  $sha=[Security.Cryptography.SHA256]::Create();try{$hash=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($actual))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}
  if($hash -ne $entry.Value){throw "Source changed since review: $($entry.Name)"}
 }
 $newFiles=@('auth.module.ts','session-issuance.service.ts','session-persistence.service.ts','session-database.service.ts','password-change.controller.ts','password-change.service.ts','password-credential-database.service.ts','password-change.service.spec.ts')
 foreach($name in @('password-change.controller.ts','password-change.service.ts','password-credential-database.service.ts','password-change.service.spec.ts')){if(Test-Path (Join-Path $project ('src\auth\'+$name))){throw "Destination exists; inspect prior results: $name"}}
 # Refresh auth source from current working checkpoint; dependencies remain isolated.
 foreach($file in Get-ChildItem (Join-Path $project 'src\auth') -File){Copy-Item $file.FullName (Join-Path $clean ('src\auth\'+$file.Name)) -Force}
 foreach($name in $newFiles){Copy-Item (Join-Path $payload $name) (Join-Path $clean ('src\auth\'+$name)) -Force}
 New-Item -ItemType Directory -Path (Join-Path $clean 'web\account-sessions') -Force | Out-Null
 foreach($name in @('index.html','app.js','style.css')){Copy-Item (Join-Path $payload $name) (Join-Path $clean ('web\account-sessions\'+$name)) -Force}
 $migrationDir=Join-Path $clean 'sql\migrations'
 Copy-Item (Join-Path $project 'sql\migrations\*') $migrationDir -Force
 $manifestPath=Join-Path $migrationDir 'manifest.json'
 $manifestBefore=Get-Content $manifestPath -Raw | ConvertFrom-Json
 if($manifestBefore.migrations.Count -ne 2 -or $manifestBefore.migrations[1].id -ne '0003_self_session_management'){throw 'Unexpected approved migration history.'}
 $migration=Join-Path $migrationDir '0004_password_change.sql'
 Copy-Item (Join-Path $payload '0004_password_change.sql') $migration -Force
 $manifestBefore.migrations=@($manifestBefore.migrations)+@([ordered]@{position=4;id='0004_password_change';file='sql/migrations/0004_password_change.sql';sha256=(Get-FileHash $migration -Algorithm SHA256).Hash.ToLowerInvariant()})
 [IO.File]::WriteAllText($manifestPath,($manifestBefore | ConvertTo-Json -Depth 12),(New-Object Text.UTF8Encoding($false)))
 Set-Location $clean
 $npm=(Get-Command npm.cmd -ErrorAction Stop).Source
 Run $npm @('run','build') 'production-auth-build'
 foreach($item in @(Get-ChildItem Env:)) {
  if($item.Name -match '^(PG|GYMPRO_|PRISMA_|.*DATABASE_URL$|NODE_OPTIONS$)'){[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}
 }
 $env:PGSSLMODE='disable'
 $port=$null
 foreach($candidate in 55432..55462){
  $listener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Parse('127.0.0.1'),$candidate)
  try{$listener.Start();$port=$candidate;break}catch{}finally{$listener.Stop()}
 }
 if(-not $port){throw 'No free rehearsal PostgreSQL port.'}
 $apiPort=$null
 foreach($candidate in 3151..3181){
  $listener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Parse('127.0.0.1'),$candidate)
  try{$listener.Start();$apiPort=$candidate;break}catch{}finally{$listener.Stop()}
 }
 if(-not $apiPort){throw 'No free rehearsal API port.'}
 $target='gympro_bootstrap_'+(Get-Date -Format 'yyyyMMddHHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6)
 $node=(Get-Command node.exe -ErrorAction Stop).Source
 Set-Location $clean
 Run (Join-Path $bin 'initdb.exe') @('-D',$cluster,'-U','postgres','-A','trust','--no-locale','-E','UTF8') 'initdb'
 $started=$true
 Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-l',(Join-Path $report 'server.log'),'-o',"-h 127.0.0.1 -p $port",'-w','start') 'start'
 Run (Join-Path $bin 'createdb.exe') @('-w','-h','127.0.0.1','-p',"$port",'-U','postgres','--template=template0',$target) 'createdb'
 $common=@('-X','-q','-w','-h','127.0.0.1','-p',"$port",'-U','postgres','-d',$target,'-v','ON_ERROR_STOP=1','-v',"target=$target")
 Run (Join-Path $bin 'psql.exe') ($common+@('-f',(Join-Path $bootstrapFiles '000-roles.sql'))) 'roles'
 Run (Join-Path $bin 'psql.exe') ($common+@('--single-transaction','-f',$schema)) 'schema'
 foreach($file in @('010-permissions.sql','verify-prerequisites.sql','verify-schema.sql')) {
  Run (Join-Path $bin 'psql.exe') ($common+@('-f',(Join-Path $bootstrapFiles $file))) ([IO.Path]::GetFileNameWithoutExtension($file))
 }
 # Random, throwaway rehearsal password, never printed or saved in plaintext.
 $env:GYMPRO_1F_PASSWORD=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N')
 try {Run $node @((Join-Path $payload 'verify-and-demo.mjs'),$clean,"$port",$target,"$apiPort",$report) 'clean-startup-login-e2e'} finally {$env:GYMPRO_1F_PASSWORD=$null}
 $results=Get-Content (Join-Path $report 'provisioning-results.json') -Raw | ConvertFrom-Json
 $e2e=Get-Content (Join-Path $report 'root-e2e-results.json') -Raw | ConvertFrom-Json
 if($results.automaticChecksPassed -ne $true -or $results.automaticCheckCount -ne 46 -or $results.fixtureCleanupPassed -ne $true -or $results.ownApiStopped -ne $true -or $e2e.success -ne $true){throw 'Verification or cleanup evidence incomplete.'}
 $success=$true
} catch {$failure=$_.Exception.Message;Write-Host ('FAIL: '+$failure) -ForegroundColor Red} finally {
 $env:GYMPRO_1F_PASSWORD=$null
 if($started -and (Test-Path (Join-Path $cluster 'postmaster.pid'))){try{Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-m','fast','-w','stop') 'stop'}catch{$success=$false;$failure=$_.Exception.Message;Write-Host ('FAIL: '+$failure) -ForegroundColor Red}}
}
if($success){
 try {
  Write-Host 'CHECK: Working database backup, then install the verified credential-bound issuance/password functions.' -ForegroundColor Cyan
  Write-Host 'Enter the local postgres password when prompted for backup and installation.'
  $dump=Join-Path $report 'working-before-password-change.dump'
  Run (Join-Path $bin 'pg_dump.exe') @('-W','-h','127.0.0.1','-p','5432','-U','postgres','-d','gympro_saas','-Fc','-f',$dump) 'working-backup'
  Run (Join-Path $bin 'pg_restore.exe') @('--list',$dump) 'backup-list'
  Run (Join-Path $bin 'psql.exe') @('-X','-W','-h','127.0.0.1','-p','5432','-U','postgres','-d','gympro_saas','-v','ON_ERROR_STOP=1','--single-transaction','-f',(Join-Path $payload '0004_password_change.sql')) 'install-password-functions'
  foreach($name in $newFiles){$destination=Join-Path $project ('src\auth\'+$name);if(Test-Path $destination){Copy-Item $destination (Join-Path $report ($name+'.working-before.bak'))};Copy-Item (Join-Path $payload $name) $destination -Force}
  foreach($name in @('index.html','app.js')){$destination=Join-Path $project ('web\account-sessions\'+$name);Copy-Item $destination (Join-Path $report ($name+'.working-before.bak'));Copy-Item (Join-Path $payload $name) $destination -Force}
  Copy-Item (Join-Path $payload '0004_password_change.sql') (Join-Path $project 'sql\migrations\0004_password_change.sql')
  Copy-Item (Join-Path $project 'sql\migrations\manifest.json') (Join-Path $report 'working-manifest.before.json')
  Copy-Item (Join-Path $clean 'sql\migrations\manifest.json') (Join-Path $project 'sql\migrations\manifest.json') -Force
  $suite=Get-Content (Join-Path $report 'full-suite-results.json') -Raw | ConvertFrom-Json
  [ordered]@{batch='Authenticated password changes';fullSuitePassed=$true;passedTests=$suite.numPassedTests;skippedTests=$suite.numPendingTests;rootE2ePassed=$true;httpDatabaseChecks=46;credentialBoundIssuanceVerified=$true;concurrentChangeVerified=$true;allTenantSessionRevocationVerified=$true;legacyRuntimeIssuanceDisabled=$true;fixturesRemoved=$true;ownApiStopped=$true;clusterStopped=$true;workingSchemaFunctionsInstalled=$true;workingUserRowsChanged=$false;workingEnvironmentChanged=$false;liveMigrationLedgerAdopted=$false;browserAcceptance='pending';recoveryInstalled=$false;productionReady=$false;kbzPayDeferred=$true;verifiedAt=(Get-Date -Format o)} | ConvertTo-Json | Set-Content (Join-Path $report 'password-change-summary.json') -Encoding UTF8
  Copy-Item (Join-Path $report 'password-change-summary.json') (Join-Path $project 'docs\completion\password-change-summary.json')
  Copy-Item $PSCommandPath (Join-Path $project 'scripts\completion-password-change.ps1') -Force
  Write-Host 'PASS: Full tests, production e2e and 46 HTTP/database checks passed.' -ForegroundColor Green
  Write-Host 'PASS: Credential-bound issuance, concurrent password change and all-tenant session revocation verified; fixtures removed and own cluster stopped.'
  Write-Host 'PASS: Working database backed up; verified functions/source/UI installed. No existing user password or session rows changed.'
  Write-Host 'PENDING: Browser acceptance, recovery, MFA and deployment security. Restart using your operator start script after this runner exits.'
 }catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}
}
Write-Host "Reports: $report"
Write-Host 'No .env change or Git commit. KBZPay deferred. Do not reinstall over a partial failure.'
if(-not $success){$safeLog=Join-Path $report 'password-api-errors.log';if(Test-Path $safeLog){Select-String -LiteralPath $safeLog -SimpleMatch 'Password change database failure' | Select-Object -Last 3 | ForEach-Object {Write-Host $_.Line}};exit 1}
